<script setup lang="ts">
import {ref,reactive,onBeforeUnmount} from 'vue';
import {metadata,type CatalogOption} from '../services/metadata';
import {collectionsChanged} from '../stores/collections';
import GroupManager from './GroupManager.vue';
type Row=CatalogOption&{revision?:number;enabled?:boolean};type TagPlan={tag_id:string;revision:number;userAssets:{asset_id:string;revision:number}[];aiReferences:number;canDelete:boolean};type CreatorPlan={creator_id:string;revision:number;assetLinks:number;packageLinks:number;canDelete:boolean};
const kind=ref('creators'),rows=ref<Row[]>([]),cursor=ref<string|null>(null),selected=ref(''),revision=ref(0),baseVersion=ref(''),usage=ref(0),plan=ref<TagPlan>(),deletePlan=ref<CreatorPlan|TagPlan>(),confirmed=ref(false),enabled=ref(true),ready=ref(false),busy=ref(false),error=ref(''),notice=ref(''),conflict=ref(false),dirty=ref(false),form=reactive<Record<string,string>>({});let epoch=0,baseline='';onBeforeUnmount(()=>epoch++);
const creatorFields=[['name','이름',128],['brand','브랜드',128],['homepageUrl','홈페이지',512],['profileUrl','판매자 프로필',512],['contact','연락처',256],['country','국가',64],['description','설명',512]] as const;
function snapshot(){return JSON.stringify({form:{...form},enabled:enabled.value});}
function cancel(){if(baseline){const s=JSON.parse(baseline);Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,s.form);enabled.value=s.enabled;}dirty.value=false;deletePlan.value=undefined;confirmed.value=false;}
function fresh(){Object.keys(form).forEach(k=>delete form[k]);for(const [key] of creatorFields)form[key]='';Object.assign(form,{kind:'person',label:'',code:'',axis:kind.value==='types'?'type':'style',ko:'',en:'',aliases:'',replacement:''});selected.value='';revision.value=0;usage.value=0;plan.value=undefined;ready.value=true;enabled.value=true;confirmed.value=false;deletePlan.value=undefined;conflict.value=false;dirty.value=false;baseline=snapshot();}
function startNew(){if(dirty.value){error.value='초안을 저장하거나 취소한 뒤 새 항목을 만드세요.';return;}fresh();}
function switchKind(event:Event){if(dirty.value){error.value='초안을 저장하거나 취소한 뒤 사전을 바꾸세요.';(event.target as HTMLSelectElement).value=kind.value;return;}epoch++;kind.value=(event.target as HTMLSelectElement).value;baseVersion.value='';busy.value=false;rows.value=[];cursor.value=null;error.value='';fresh();}
async function list(more=false){if(busy.value||kind.value==='groups')return;const token=++epoch;busy.value=true;error.value='';try{
 const r=kind.value==='creators'?await metadata<{items:Row[];next_cursor:string|null}>('creator.list',{after_id:more?cursor.value:null,include_disabled:true}):await metadata<{items:Row[];next_cursor:string|null;version?:string}>('catalog.options',{kind:kind.value,after_id:more?cursor.value:null,include_inactive:true});if(token!==epoch)return;
 rows.value=more?[...rows.value,...r.items]:r.items;cursor.value=r.next_cursor;if('version' in r&&!selected.value&&!dirty.value)baseVersion.value=String(r.version);if(!ready.value)fresh();
 }catch{if(token===epoch)error.value='사전을 조회하지 못했습니다. 초안을 유지합니다.';}finally{if(token===epoch)busy.value=false;}}
async function edit(row:Row,privateApproved=false){if(dirty.value){error.value='초안을 저장하거나 취소한 뒤 선택하세요.';return;}const token=++epoch;busy.value=true;error.value='';try{
 if(kind.value==='creators'){selected.value=row.id;revision.value=row.revision??0;enabled.value=row.enabled??true;ready.value=false;if(!privateApproved)return;const r=await metadata<Record<string,string|number|boolean>>('creator.get',{creator_id:row.id,include_private:true,confirmed:true});if(token!==epoch)return;for(const [key] of creatorFields)form[key]=String(r[key]??'');form.kind=String(r.kind);revision.value=Number(r.revision);enabled.value=Boolean(r.enabled);}
 else if(kind.value==='tags'){const r=await metadata<{label:string;revision:number;enabled:boolean;plan:TagPlan}>('catalog.tag.get',{tag_id:row.id});if(token!==epoch)return;selected.value=row.id;form.label=r.label;revision.value=r.revision;enabled.value=r.enabled;plan.value=r.plan;}
 else{const r=await metadata<{base_version:string;usedAssets:number;value:{code:string;axis:string;ko:string;en:string;aliases:string[];active:boolean;replacement:string|null}}>('catalog.term.get',{kind:kind.value==='types'?'type':'facet',code:row.id});if(token!==epoch)return;selected.value=row.id;baseVersion.value=r.base_version;usage.value=r.usedAssets;Object.assign(form,{...r.value,aliases:r.value.aliases.join('\n'),replacement:r.value.replacement??''});enabled.value=r.value.active;}
 if(token===epoch){ready.value=true;dirty.value=false;conflict.value=false;deletePlan.value=undefined;confirmed.value=false;baseline=snapshot();}
 }catch{if(token===epoch)error.value='선택 항목을 불러오지 못했습니다.';}finally{if(token===epoch)busy.value=false;}}
async function save(){if(!ready.value||busy.value||conflict.value||(kind.value!=='creators'&&!confirmed.value))return;const token=epoch;busy.value=true;error.value='';try{
 if(kind.value==='creators'){const value=Object.fromEntries([...creatorFields.map(([key])=>[key,form[key]]),['kind',form.kind]]);const r=await metadata<{id:string;revision:number}>(selected.value?'creator.update':'creator.create',{...(selected.value?{creator_id:selected.value,expected_revision:revision.value}:{}),value});if(token!==epoch)return;selected.value=r.id;revision.value=r.revision;}
 else if(kind.value==='tags'){const r=await metadata<{id:string;revision:number;plan:TagPlan}>('catalog.tag.save',{tag_id:selected.value||null,value:{label:form.label,enabled:enabled.value},plan:plan.value??null,confirmed:true});if(token!==epoch)return;selected.value=r.id;revision.value=r.revision;plan.value=r.plan;}
 else{const r=await metadata<{version:string}>('catalog.term.save',{kind:kind.value==='types'?'type':'facet',base_version:baseVersion.value,value:{code:form.code,axis:form.axis,ko:form.ko,en:form.en,aliases:kind.value==='types'?form.aliases!.split('\n').map(s=>s.trim()).filter(Boolean):[],active:enabled.value,replacement:form.replacement||null},expected_usage:usage.value,confirmed:true});if(token!==epoch)return;baseVersion.value=r.version;selected.value=form.code!;}
 if(token===epoch){dirty.value=false;confirmed.value=false;baseline=snapshot();notice.value='공유 사전을 저장했습니다. 기존 AI 결과와 이전 분류 버전은 보존됩니다.';collectionsChanged();}
 }catch(e){if(token===epoch){conflict.value=e instanceof Error&&e.message==='METADATA_CONFLICT';error.value=conflict.value?'검토 이후 사전/참조가 변경되었습니다. 초안을 유지하고 다시 조회하세요.':'사전을 저장하지 못했습니다. 입력·중복·하위 분류·대체값을 확인하세요.';}}finally{if(token===epoch)busy.value=false;}}
async function toggleCreator(){if(!selected.value||busy.value)return;const token=epoch;busy.value=true;try{const r=await metadata<{revision:number;enabled:boolean}>('creator.set_enabled',{creator_id:selected.value,enabled:!enabled.value,expected_revision:revision.value});if(token===epoch){revision.value=r.revision;enabled.value=r.enabled;baseline=snapshot();collectionsChanged();}}catch{if(token===epoch){conflict.value=true;error.value='활성 상태를 저장하지 못했습니다. 다시 조회하세요.';}}finally{if(token===epoch)busy.value=false;}}
async function reviewDelete(){if(!selected.value||busy.value)return;const token=epoch;busy.value=true;try{const r=kind.value==='creators'?await metadata<CreatorPlan>('creator.delete.preview',{creator_id:selected.value}):(await metadata<{plan:TagPlan}>('catalog.tag.get',{tag_id:selected.value})).plan;if(token===epoch){deletePlan.value=r;confirmed.value=false;}}catch{if(token===epoch)error.value='삭제 영향을 조회하지 못했습니다.';}finally{if(token===epoch)busy.value=false;}}
async function remove(){if(!deletePlan.value?.canDelete||!confirmed.value||busy.value)return;const token=epoch;busy.value=true;try{await metadata(kind.value==='creators'?'creator.delete':'catalog.tag.delete',{plan:deletePlan.value,confirmed:true});if(token===epoch){fresh();notice.value='참조 없는 사전 항목을 삭제했습니다. 기존 에셋/AI/원본은 보존됩니다.';collectionsChanged();}}catch{if(token===epoch)error.value='삭제 검토 후 변경되었거나 참조가 남아 있습니다. 다시 검토하세요.';}finally{if(token===epoch)busy.value=false;}}
</script>
<template><details class="catalog-manager"><summary>공유 사전 관리</summary><label>관리할 사전<select :value="kind" @change="switchKind"><option value="creators">제작 주체</option><option value="types">유형 분류</option><option value="facets">독립 분류 축</option><option value="tags">태그 사전</option><option value="groups">그룹</option></select></label>
 <GroupManager v-if="kind==='groups'" /><template v-else><button type="button" :disabled="busy" @click="list()">사전 목록 조회</button><button v-if="cursor" type="button" :disabled="busy" @click="list(true)">사전 더 보기</button><button type="button" :disabled="busy" @click="startNew">새 사전 항목</button>
 <ul><li v-for="row in rows" :key="row.id"><button type="button" :disabled="busy" @click="edit(row)">{{row.name}}{{row.enabled===false?' (비활성)':''}}</button></li></ul>
 <p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><button v-if="kind==='creators'&&selected" type="button" :disabled="busy" @click="edit({id:selected,name:'',revision},true)">연락처·프로필 원문 조회 승인</button>
 <form @submit.prevent="save" @input="dirty=true;deletePlan=undefined" @change="dirty=true;deletePlan=undefined"><fieldset :disabled="busy||!ready"><template v-if="kind==='creators'"><label v-for="[key,label,max] in creatorFields" :key="key">{{label}}<input v-model="form[key]" :maxlength="max" /></label><label>주체 유형<select v-model="form.kind"><option value="person">개인</option><option value="team">팀</option><option value="company">회사</option></select></label></template>
 <label v-else-if="kind==='tags'">공유 태그 이름<input v-model="form.label" maxlength="64" /></label>
 <template v-else><p>새 사전 버전으로 저장합니다. 기존 에셋의 이전 버전은 자동 변경하지 않습니다. 연결된 에셋 {{usage}}개.</p><label>분류 코드<input v-model="form.code" :disabled="!!selected" maxlength="64" /></label><label>분류 축<select v-model="form.axis" :disabled="kind==='types'||!!selected"><option value="type">유형</option><option v-for="axis in ['role','style','genre','view','dimension','engine']" :key="axis" :value="axis">{{axis}}</option></select></label><label>한국어 이름<input v-model="form.ko" maxlength="64" /></label><label>영어 이름<input v-model="form.en" maxlength="64" /></label><label v-if="kind==='types'">분류 별칭 (한 줄에 하나)<textarea v-model="form.aliases" /></label><label v-else>비활성 시 대체 코드<input v-model="form.replacement" maxlength="64" /></label></template>
 <label v-if="kind!=='creators'"><input v-model="enabled" type="checkbox" />활성</label><p v-if="plan">사용자 연결 {{plan.userAssets.length}}개 · AI 참조 {{plan.aiReferences}}개. 한 에셋의 태그 제거는 기본 정보 탭에서 합니다.</p>
 <label v-if="kind!=='creators'||deletePlan"><input v-model="confirmed" type="checkbox" />영향을 검토한 사전 변경 승인</label><button :disabled="conflict||(kind!=='creators'&&!confirmed)">사전 항목 저장</button><button type="button" @click="cancel">사전 변경 취소</button></fieldset></form>
 <button v-if="kind==='creators'&&selected" type="button" :disabled="busy||conflict||dirty" @click="toggleCreator">{{enabled?'주체 비활성화':'주체 활성화'}}</button><template v-if="selected&&(kind==='creators'||kind==='tags')"><button type="button" :disabled="busy" @click="reviewDelete">사전 삭제 영향 검토</button><p v-if="deletePlan">삭제 가능: {{deletePlan.canDelete?'참조 없음':'연결이 있어 삭제 거부'}}. 원본과 AI 이력은 삭제하지 않습니다.</p><button v-if="deletePlan" type="button" :disabled="busy||!confirmed||!deletePlan.canDelete" @click="remove">검토한 사전 항목 삭제</button></template>
 </template></details></template>
